namespace sv_9dcd9d424fc84bc98a6a85c6660fd716.Auth;

public sealed class UserInfo
{
    public required string Email { get; init; }
    public required string[] Roles { get; init; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Components.Web;

namespace sv_9dcd9d424fc84bc98a6a85c6660fd716.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that hardcodes a logged-in user
/// and persists auth state so the WebAssembly client can pick it up.
/// </summary>
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    public ServerAuthenticationStateProvider(PersistentComponentState persistentState)
        : base(persistentState)
    {
    }

    protected override UserInfo? GetUserInfo(ClaimsPrincipal principal)
    {
        // We always return our hardcoded user regardless of the principal.
        return HardcodedUser;
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, HardcodedUser.Email),
            new(ClaimTypes.Email, HardcodedUser.Email)
        };

        foreach (var role in HardcodedUser.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "Hardcoded");
        var user = new ClaimsPrincipal(identity);

        return Task.FromResult(new AuthenticationState(user));
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_9dcd9d424fc84bc98a6a85c6660fd716.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that hardcodes a logged-in user
/// and persists auth state into PersistentComponentState so the WebAssembly
/// client can restore it after the runtime takes over.
/// </summary>
public sealed class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public PersistingAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        _subscription = persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authStateTask = authenticationStateTask;
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        if (_authStateTask is not null)
            return _authStateTask;

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, HardcodedUser.Email),
            new(ClaimTypes.Email, HardcodedUser.Email)
        };

        foreach (var role in HardcodedUser.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "Hardcoded");
        var user = new ClaimsPrincipal(identity);
        _authStateTask = Task.FromResult(new AuthenticationState(user));
        return _authStateTask;
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var userInfo = new UserInfo
            {
                Email = principal.FindFirst(ClaimTypes.Email)?.Value ?? principal.Identity.Name ?? "",
                Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray()
            };

            _persistentState.PersistAsJson(nameof(UserInfo), userInfo);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_9dcd9d424fc84bc98a6a85c6660fd716.Client.Auth;

/// <summary>
/// Client-side AuthenticationStateProvider that restores auth state
/// from PersistentComponentState (serialized by the server).
/// </summary>
public sealed class ClientAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> UnauthenticatedState =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authStateTask;

    public ClientAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) && userInfo is not null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, userInfo.Email),
                new(ClaimTypes.Email, userInfo.Email)
            };

            foreach (var role in userInfo.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var identity = new ClaimsIdentity(claims, "Hardcoded");
            var user = new ClaimsPrincipal(identity);
            _authStateTask = Task.FromResult(new AuthenticationState(user));
        }
        else
        {
            _authStateTask = UnauthenticatedState;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authStateTask;
}

